def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The background is the most frequent color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def edge_runs(col):
        runs = []
        r = 0
        while r < h:
            color = grid[r][col]
            if color == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][col] == color:
                r += 1
            runs.append((start, r, color))
        return runs

    left_runs = edge_runs(0)
    right_runs = edge_runs(w - 1)
    pairs = []
    for ls, le, lc in left_runs:
        for rs, re, rc in right_runs:
            if lc == rc and le - ls == re - rs:
                pairs.append((ls, le, rs, re))

    edge_colors = {color for _, _, color in left_runs + right_runs}
    marker_colors = {
        value for row in grid for value in row
        if value != bg and value not in edge_colors
    }

    for ls, le, rs, re in pairs:
        for r in range(h):
            for c in range(1, w - 1):
                color = grid[r][c]
                if color not in marker_colors:
                    continue

                if ls <= r < le:
                    paired_r = rs + r - ls
                    out[r][c] = 4
                    for x in range(1, c):
                        out[r][x] = color
                elif rs <= r < re:
                    paired_r = ls + r - rs
                    out[r][c] = 4
                    for x in range(c + 1, w - 1):
                        out[r][x] = color
                else:
                    continue

                # Project a full line across the grid, leaving existing
                # colored border markers untouched.
                for x in range(w):
                    if x not in (0, w - 1) or grid[paired_r][x] == bg:
                        out[paired_r][x] = color

    return out
